    if (audioCtx.state !== 'running') audioCtx.resume();
    // Play a short move tone for left/right arrows or A/D keys
    if ((e.key === 'ArrowLeft' || e.key === 'a' || e.key === 'ArrowRight' || e.key === 'd') && !keys[e.key]) {
      playTone(300, 0.07);
    }
    keys[e.key] = true;
  });

